from datetime import datetime
from typing import ClassVar
from uuid import UUID

from sqlalchemy import Column, DateTime, Enum as SQLEnum, Text, func
from sqlalchemy.dialects.postgresql import JSONB, UUID as PGUUID
from sqlmodel import Field, SQLModel, text

from app.models.enums import ProblemDifficulty


class Problem(SQLModel, table=True):
    __tablename__: ClassVar[str] = "problem"

    # we make it optional to prevent pydantic validation error when creating a new problem, as the id will be generated by the supabase database.
    # If we don't make it optional, pydantic will throw a validation error when we try to create a new problem without providing an id.
    id: UUID | None = Field(
        default=None,
        sa_column=Column(
            PGUUID(as_uuid=True),
            server_default=text("uuid_generate_v4()"),
            primary_key=True,
            nullable=False,
        ),
    )
    title: str = Field(nullable=False)
    description: str = Field(default="", sa_column=Column(Text, nullable=False))
    difficulty: ProblemDifficulty = Field(
        sa_column=Column(
            SQLEnum(
                ProblemDifficulty,
                name="problem_difficulty_enum",
                native_enum=True,
                values_callable=lambda x: [v.value for v in x],
            ),
            nullable=False,
        ),
    )
    test_case: dict = Field(  # changed from list[dict] to dict to match database model, as the test_case is stored as a JSONB object in the database
        default_factory=dict, sa_column=Column(JSONB, nullable=False)
    )
    start_code: str = Field(default="", sa_column=Column(Text, nullable=False))
    created_at: datetime = Field(
        default=None,
        sa_column=Column(DateTime(timezone=True), nullable=False, server_default=func.now()),
    )
    updated_at: datetime = Field(
        default=None,
        sa_column=Column(
            DateTime(timezone=True),
            nullable=False,
            server_default=func.now(),
            onupdate=func.now(),
        ),
    )
